python3 << 'EOF'
import os, re, subprocess

# Step 1: find all files with timer registrations
roots = ['drivers', 'net', 'kernel', 'fs', 'mm', 'block', 'security', 'ipc', 'lib']
timer_pat = re.compile(r'timer_setup\s*\(|setup_timer\s*\(|DEFINE_TIMER\s*\(|hrtimer_init\s*\(|\.function\s*=\s*([a-zA-Z_0-9]+)')
plain_lock_pat = re.compile(r'spin_lock\s*\(&?([a-zA-Z_0-9>\.\-\[\]]+)')

results = {}
for root in roots:
    for dirpath, dirnames, filenames in os.walk(root):
        for fn in filenames:
            if not fn.endswith('.c'):
                continue
            p = os.path.join(dirpath, fn)
            try:
                with open(p, errors='ignore') as f:
                    src = f.read()
            except Exception:
                continue
            timers = timer_pat.findall(src)
            if not timers:
                continue
            plain = plain_lock_pat.findall(src)
            if not plain:
                continue
            # a file that has both timer registrations and plain spin_locks
            results[p] = (len(timers), len(plain))

ranked = sorted(results.items(), key=lambda kv: -kv[1][1])
for p, (t, l) in ranked[:40]:
    print(f"{p}\t timers={t} plain_spin_locks={l}")
EOF

